function readRouteState(): RouteState {
  if (typeof window === 'undefined') return { view: 'leaderboard', extremeMode: false, query: '', country: 'All countries', sortKey: 'Total Score', descending: true, historyMode: 'monthly', historyPeriod: '', historyYear: '', winnerYear: '', runQuery: '', runGame: 'All games', lineageGame: 'smb1', lineageBoard: '', labMode: 'simulator', labRunner: '', profileRunner: null, profileTab: 'overview', compareOpen: false, runnerA: 'Niftski', runnerB: '', excludedGames: [], excludedBoards: [] };
  const params = new URLSearchParams(window.location.search);
  const requestedView = params.get('view');
  const view = requestedView === 'extreme' ? 'leaderboard' : views.has(requestedView as View) ? requestedView as View : 'leaderboard';
  const requestedSort = params.get('sort') as SortKey;
  const requestedLabMode = params.get('labTool') as LabMode;
  return {
    view,
    extremeMode: requestedView === 'extreme' || params.get('extreme') === '1',
    query: params.get('q') || '', country: params.get('country') || 'All countries',
    sortKey: sortKeys.has(requestedSort) ? requestedSort : 'Total Score', descending: params.get('direction') !== 'asc',
    historyMode: params.get('historyMode') === 'yearly' ? 'yearly' : 'monthly', historyPeriod: params.get('period') || '', historyYear: params.get('historyYear') || '', winnerYear: params.get('winnerYear') || '',
    runQuery: params.get('runQuery') || '', runGame: params.get('runGame') || 'All games',
    lineageGame: params.get('lineageGame') || 'smb1', lineageBoard: params.get('lineageBoard') || '',
    labMode: labModes.has(requestedLabMode) ? requestedLabMode : 'simulator', labRunner: params.get('labRunner') || '',
    profileRunner: params.get('profile') || null, profileTab: params.get('profileTab') === 'audit' ? 'audit' : 'overview',
    compareOpen: params.get('compare') === '1', runnerA: params.get('runnerA') || 'Niftski', runnerB: params.get('runnerB') || '',
    excludedGames: (params.get('excludeGames') || '').split(',').filter(Boolean), excludedBoards: (params.get('excludeBoards') || '').split(',').filter(Boolean),
  };
}

